import React, { useState } from "react";
import TabSetting from "./tabSetting";
import TabClassic from "./tabClassic";
import TabHot from "./tabHot";
import "../css/content.css";
import playerAbove from "../img/playerAbove.png";
import useStore from "../store";
import player from "../img/player.png";
const Content = () => {
  const [showContent, setShowContent] = useState(0);
  const img = useStore((state) => state.img);
  const items = [
    {
      key: 0,
      label: "自定义",
      children: <TabSetting />,
    },
    {
      key: 1,
      label: "热门",
      children: <TabHot />,
    },
    {
      key: 2,
      label: "经典",
      children: <TabClassic />,
    },
    {
      key: 3,
      label: "明星",
      children: <TabHot />,
    },
    {
      key: 4,
      label: "动漫",
      children: <TabClassic />,
    },
  ];
  const onChange = (key) => {
    setShowContent(key);
  };
  return (
    <div className="content">
      <div
        className="background"
        style={{ backgroundImage: `url(${img ? img : player})` }}
      ></div>
      <div className="setting">
        <div className="setting_tabs_container">
          {items.map((item) => (
            <div
              key={item.key}
              className={
                showContent === item.key
                  ? "setting_tab setting_tab_active"
                  : "setting_tab"
              }
              onClick={() => onChange(item.key)}
            >
              {item.label}
            </div>
          ))}
        </div>
        <div className="setting_tabs_content">
          {items[showContent].children}
        </div>
      </div>
    </div>
  );
};

export default Content;
